import time
import threading
import json
from collections import deque

class ESP32Simulator:

    def __init__(self, on_serial_output_callback=None):
        self.on_serial_output_callback = on_serial_output_callback
        self.bin_full_threshold_cm = 15
        self.pet_nir_w_min = 200
        self.pet_nir_w_max = 5000
        self.entrance_gate_timeout = 60
        self.settle_time_ms = 500
        self.success_drop_tout_ms = 3000
        self.reject_drop_time_ms = 2000
        self.ent_open_angle = 90
        self.ent_close_angle = 0
        self.suc_open_angle = 90
        self.suc_close_angle = 0
        self.rej_open_angle = 90
        self.rej_close_angle = 0
        self.entrance_servo_angle = 0
        self.success_servo_angle = 0
        self.reject_servo_angle = 0
        self.buzzer_state = False
        self.led_green = False
        self.led_red = False
        self.bin_distance_cm = 60
        self.is_bin_full = False
        self.top_ir_triggered = False
        self.bottom_ir_triggered = False
        self.prox_metal_detected = False
        self.prox_capacitive_plastic = True
        self.nir_spectrometer_val = 1450
        self.pipe_item_type = 'none'
        self.pipe_item_stage = 'idle'
        self.pipe_scan_active = False
        self.current_session_bottles = 0
        self.entrance_gate_requested = False
        self.force_gate_close = False
        self.lcd_lines = ['=== ECO-Fi VENDO ===', 'Ready for Deposit   ', 'Rate: 1 Bottle = 10m', 'Session Bottles: 0  ']
        self.oled_text = 'Eco-Fi Vendo Ready'
        self.serial_logs = deque(maxlen=100)
        self.lock = threading.RLock()
        self.running = True
        self.worker_thread = threading.Thread(target=self._run_loop, daemon=True)
        self.worker_thread.start()

    def set_lcd(self, line0=None, line1=None, line2=None, line3=None):
        with self.lock:
            if line0 is not None:
                self.lcd_lines[0] = str(line0).ljust(20)[:20]
            if line1 is not None:
                self.lcd_lines[1] = str(line1).ljust(20)[:20]
            if line2 is not None:
                self.lcd_lines[2] = str(line2).ljust(20)[:20]
            if line3 is not None:
                self.lcd_lines[3] = str(line3).ljust(20)[:20]

    def log_serial(self, direction, msg):
        timestamp = time.strftime('%H:%M:%S')
        entry = {'time': timestamp, 'dir': direction, 'msg': msg}
        with self.lock:
            self.serial_logs.append(entry)
        if direction == 'TX' and self.on_serial_output_callback:
            try:
                self.on_serial_output_callback(msg)
            except Exception as e:
                print('[ESP32 Simulator] Error in serial callback: {}'.format(e))

    def send_uart(self, payload):
        msg = json.dumps(payload)
        self.log_serial('TX', msg)

    def receive_uart(self, raw_str):
        self.log_serial('RX', raw_str.strip())
        try:
            data = json.loads(raw_str)
            cmd = data.get('cmd')
            if cmd == 'OPEN_GATE':
                timeout = data.get('timeout', self.entrance_gate_timeout)
                self.open_entrance_gate(timeout)
            elif cmd == 'CLOSE_GATE':
                self.close_entrance_gate()
            elif cmd == 'TRIGGER_CONFIG':
                self.set_lcd(line0='=== ECO-Fi CONFIG ==', line1='WIFI: ECO-Fi-Config ', line2='IP: 192.168.4.1     ', line3='Port: 80 / AP Active')
            elif cmd == 'SET_CONFIG':
                with self.lock:
                    if 'bin_full_threshold_cm' in data:
                        self.bin_full_threshold_cm = data['bin_full_threshold_cm']
                    if 'entrance_gate_timeout' in data:
                        self.entrance_gate_timeout = data['entrance_gate_timeout']
                    if 'settle_time_ms' in data:
                        self.settle_time_ms = data['settle_time_ms']
                    if 'success_drop_tout_ms' in data:
                        self.success_drop_tout_ms = data['success_drop_tout_ms']
                    if 'reject_drop_time_ms' in data:
                        self.reject_drop_time_ms = data['reject_drop_time_ms']
                    if 'pet_nir_w_min' in data:
                        self.pet_nir_w_min = data['pet_nir_w_min']
                    if 'pet_nir_w_max' in data:
                        self.pet_nir_w_max = data['pet_nir_w_max']
                    if 'ent_open_angle' in data:
                        self.ent_open_angle = data['ent_open_angle']
                    if 'ent_close_angle' in data:
                        self.ent_close_angle = data['ent_close_angle']
                    if 'suc_open_angle' in data:
                        self.suc_open_angle = data['suc_open_angle']
                    if 'suc_close_angle' in data:
                        self.suc_close_angle = data['suc_close_angle']
                    if 'rej_open_angle' in data:
                        self.rej_open_angle = data['rej_open_angle']
                    if 'rej_close_angle' in data:
                        self.rej_close_angle = data['rej_close_angle']
                    self.entrance_servo_angle = self.ent_close_angle
                    self.success_servo_angle = self.suc_close_angle
                    self.reject_servo_angle = self.rej_close_angle
                self.send_uart({'event': 'CONFIG_SAVED'})
        except Exception:
            if '"OPEN_GATE"' in raw_str:
                self.open_entrance_gate(self.entrance_gate_timeout)
            elif '"CLOSE_GATE"' in raw_str:
                self.close_entrance_gate()

    def open_entrance_gate(self, timeout=60):
        with self.lock:
            self.entrance_gate_timeout = timeout
            self.entrance_gate_requested = True

    def close_entrance_gate(self):
        with self.lock:
            self.force_gate_close = True
            self.entrance_servo_angle = self.ent_close_angle
            self.led_green = False

    def buzz(self, duration_sec=0.12, pulses=1):

        def _buzz():
            for _ in range(pulses):
                self.buzzer_state = True
                time.sleep(duration_sec)
                self.buzzer_state = False
                if pulses > 1:
                    time.sleep(0.08)
        threading.Thread(target=_buzz, daemon=True).start()

    def _run_loop(self):
        last_ultrasonic_check = time.time()
        last_bin_state = False
        while self.running:
            now = time.time()
            if now - last_ultrasonic_check >= 1.0:
                currently_full = 0 < self.bin_distance_cm < self.bin_full_threshold_cm
                if currently_full != last_bin_state:
                    self.is_bin_full = currently_full
                    last_bin_state = currently_full
                    if currently_full:
                        self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='STATUS: STORAGE FULL', line2='Empty Bin Required  ', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
                        self.led_red = True
                        self.send_uart({'event': 'BIN_FULL'})
                    else:
                        self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='Ready for Deposit   ', line2='Rate: 1 Bottle = 10m', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
                        self.led_red = False
                        self.send_uart({'event': 'BIN_OK'})
                last_ultrasonic_check = now
            if self.is_bin_full:
                time.sleep(0.1)
                continue
            if self.entrance_gate_requested:
                self.entrance_gate_requested = False
                self._handle_entrance_cycle()
            time.sleep(0.05)

    def _handle_entrance_cycle(self):
        with self.lock:
            self.entrance_servo_angle = self.ent_open_angle
            self.top_ir_triggered = False
            self.force_gate_close = False
            self.led_green = False
            self.led_red = False
            self.pipe_item_stage = 'intake'
        self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='GATE OPEN: INSERT...', line2='Drop within {}s   '.format(self.entrance_gate_timeout), line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
        start_time = time.time()
        dropped = False
        was_forced = False
        while time.time() - start_time < self.entrance_gate_timeout:
            if self.top_ir_triggered or self.force_gate_close:
                if self.top_ir_triggered:
                    dropped = True
                if self.force_gate_close:
                    was_forced = True
                break
            time.sleep(0.02)
        with self.lock:
            self.entrance_servo_angle = self.ent_close_angle
            self.force_gate_close = False
            self.pipe_item_stage = 'airlock' if dropped else 'idle'
        if not dropped:
            with self.lock:
                self.pipe_item_stage = 'idle'
                self.pipe_item_type = 'none'
                self.entrance_servo_angle = self.ent_close_angle
                self.led_green = False
                self.led_red = False
            self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='Ready for Deposit   ', line2='Rate: 1 Bottle = 10m', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
            if not was_forced:
                self.send_uart({'event': 'TIMEOUT'})
            return
        with self.lock:
            self.pipe_item_stage = 'scanning'
            self.pipe_scan_active = True
        self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='STATUS: SCANNING... ', line2='Analyzing Material  ', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
        time.sleep(self.settle_time_ms / 1000.0)
        with self.lock:
            self.pipe_scan_active = False
        is_valid = True
        reject_display = 'No Plastic Detected '
        if self.prox_metal_detected:
            is_valid = False
            reject_display = 'Tin/Can Detected    '
        elif not self.prox_capacitive_plastic:
            is_valid = False
            reject_display = 'No Plastic Detected '
        elif not self.pet_nir_w_min <= self.nir_spectrometer_val <= self.pet_nir_w_max:
            is_valid = False
            reject_display = 'Invalid Material NIR'
        if is_valid:
            self.led_green = True
            with self.lock:
                self.pipe_item_stage = 'success_drop'
                self.bottom_ir_triggered = False
                self.success_servo_angle = self.suc_open_angle
            self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='STATUS: VERIFIED OK ', line2='Dropping to bin...  ', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
            gate_open_time = time.time()
            passed_drop = False
            while time.time() - gate_open_time < self.success_drop_tout_ms / 1000.0:
                if self.bottom_ir_triggered:
                    passed_drop = True
                    break
                time.sleep(0.02)
            with self.lock:
                self.success_servo_angle = self.suc_close_angle
            if passed_drop:
                self.current_session_bottles += 1
                self.buzz(duration_sec=0.12, pulses=2)
                self.send_uart({'event': 'CREDIT_ADD', 'bottles': 1, 'sessionTotal': self.current_session_bottles})
                self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='STATUS: BOTTLE SAVED', line2='Ready for Deposit   ', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
                time.sleep(1.2)
                self.led_green = False
                with self.lock:
                    self.pipe_item_stage = 'idle'
                    self.pipe_item_type = 'none'
                self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='Ready for Deposit   ', line2='Rate: 1 Bottle = 10m', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
            else:
                with self.lock:
                    self.pipe_item_stage = 'stuck_chute'
                self._handle_reject('Drop / Sensor Error ', 'REJECTED')
        else:
            with self.lock:
                self.pipe_item_stage = 'reject_drop'
            self._handle_reject(reject_display, 'REJECTED')

    def _handle_reject(self, display_msg, uart_event):
        self.led_red = True
        self.led_green = False
        self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='STATUS: REJECTED!   ', line2=display_msg, line3='Session Bottles: {:<3}'.format(self.current_session_bottles))
        self.send_uart({'event': uart_event})
        self.buzz(duration_sec=0.6, pulses=1)
        with self.lock:
            self.reject_servo_angle = self.rej_open_angle
        time.sleep(self.reject_drop_time_ms / 1000.0)
        with self.lock:
            self.reject_servo_angle = self.rej_close_angle
            self.pipe_item_stage = 'idle'
            self.pipe_item_type = 'none'
        time.sleep(1.5)
        self.led_red = False
        self.set_lcd(line0='=== ECO-Fi VENDO ===', line1='Ready for Deposit   ', line2='Rate: 1 Bottle = 10m', line3='Session Bottles: {:<3}'.format(self.current_session_bottles))

    def simulate_insert(self, item_type='valid_pet'):
        with self.lock:
            if item_type == 'valid_pet':
                self.pipe_item_type = 'pet'
            elif item_type == 'metal_can':
                self.pipe_item_type = 'metal'
            elif item_type == 'non_plastic':
                self.pipe_item_type = 'paper'
            elif item_type == 'invalid_polymer':
                self.pipe_item_type = 'pvc'
            elif item_type == 'stuck_bottle':
                self.pipe_item_type = 'stuck'
            else:
                self.pipe_item_type = 'pet'
        if not self.entrance_gate_requested and self.entrance_servo_angle == self.ent_close_angle:
            self.open_entrance_gate(timeout=15)
            time.sleep(0.1)

        def _do_drop():
            time.sleep(0.3)
            if item_type == 'timeout_cheat':
                return
            with self.lock:
                self.top_ir_triggered = True
            if item_type == 'valid_pet':
                self.prox_metal_detected = False
                self.prox_capacitive_plastic = True
                self.nir_spectrometer_val = 1450

                def _trigger_bottom():
                    time.sleep(0.9)
                    with self.lock:
                        self.bottom_ir_triggered = True
                threading.Thread(target=_trigger_bottom, daemon=True).start()
            elif item_type == 'metal_can':
                self.prox_metal_detected = True
                self.prox_capacitive_plastic = True
                self.nir_spectrometer_val = 1450
            elif item_type == 'non_plastic':
                self.prox_metal_detected = False
                self.prox_capacitive_plastic = False
                self.nir_spectrometer_val = 1450
            elif item_type == 'invalid_polymer':
                self.prox_metal_detected = False
                self.prox_capacitive_plastic = True
                self.nir_spectrometer_val = 45
            elif item_type == 'stuck_bottle':
                self.prox_metal_detected = False
                self.prox_capacitive_plastic = True
                self.nir_spectrometer_val = 1450
        threading.Thread(target=_do_drop, daemon=True).start()

    def set_bin_distance(self, distance_cm):
        with self.lock:
            self.bin_distance_cm = distance_cm

    def reset_session(self):
        with self.lock:
            self.current_session_bottles = 0
            self.pipe_item_stage = 'idle'
            self.pipe_item_type = 'none'
            self.set_lcd(line3='Session Bottles: 0  ')

    def get_state(self):
        with self.lock:
            return {'lcd_lines': list(self.lcd_lines), 'oled_text': self.oled_text, 'entrance_servo': self.entrance_servo_angle, 'success_servo': self.success_servo_angle, 'reject_servo': self.reject_servo_angle, 'buzzer': self.buzzer_state, 'led_green': self.led_green, 'led_red': self.led_red, 'bin_distance_cm': self.bin_distance_cm, 'is_bin_full': self.is_bin_full, 'top_ir': self.top_ir_triggered, 'bottom_ir': self.bottom_ir_triggered, 'prox_metal': self.prox_metal_detected, 'prox_capacitive': self.prox_capacitive_plastic, 'nir_val': self.nir_spectrometer_val, 'pipe_item_type': self.pipe_item_type, 'pipe_item_stage': self.pipe_item_stage, 'pipe_scan_active': self.pipe_scan_active, 'session_bottles': self.current_session_bottles, 'gate_requested': self.entrance_gate_requested, 'serial_logs': list(self.serial_logs)}

